function walk(n, out, depth){
  const type = n.type;
  if(type==='COMPONENT'||type==='COMPONENT_SET'){
    out.push({id:n.id,type:type,name:n.name,key:n.key,props:(n.componentProperties?Object.keys(n.componentProperties):[])});
  }
  if(n.children){ for(const c of n.children){ walk(c,out,depth+1);} }
}
