    'Topping_Bacon':'bacon','Topping_Cheese':'cheese','Topping_Mushroom':'mushroom','Topping_Avocado':'avocado',
    'Side_Fries':'fries','Side_Coleslaw':'coleslaw','Side_Salad':'salad','Side_Onion_Rings':'orings','Side_Mozzarella_Sticks':'mozz',
    'Card_Mastercard':'mc','Card_Visa':'visa'
  };

  const dbg = figma.createFrame(); dbg.name='DEBUG2'; dbg.x=-1200; dbg.y=1500; dbg.resize(600,700); dbg.fills=[];
