async function run(){
  try{
    const mediaPage = figma.getNodeById('1:4');
    await figma.setCurrentPageAsync(mediaPage);
    const info=[];
    function walk(n){
      if(n.type==='RECTANGLE'||n.type==='ELLIPSE'){
        const img = n.fills && n.fills.find(f=>f.type==='IMAGE');
        if(img && n.name && (n.name.startsWith('Burger')||n.name.startsWith('Topping')||n.name.startsWith('Side')||n.name.startsWith('Card')||n.name==='Splash_Burger_Stack')){
          info.push({name:n.name, hash:img.imageHash, w:n.width, h:n.height});
        }
      }
      if(n.children){ for(const c of n.children) walk(c); }
    }
    for(const pg of figma.root.children){ if(pg.name==='04 · Media 素材库'){ walk(pg); } }
    // switch to workspace
    const ws = figma.getNodeById('50:2');
    await figma.setCurrentPageAsync(ws);
    let imgFrame = figma.getNodeById('120:2');
    // build assets
    let created=0; const fails=[];
    for(const it of info){
      try{
        const r = figma.createRectangle();
        r.name = it.name;
        const f = {type:'IMAGE', imageHash:it.hash, scaleMode:'FILL', scalingFactor:0.5};
        r.fills=[f];
        r.x = (created%4)*220; r.y = Math.floor(created/4)*220;
        imgFrame.appendChild(r);
        created++;
      }catch(e){ fails.push(it.name+':'+e.message); }
    }
    // write summary
    const rep = figma.getNodeById('130:2');
    if(rep && rep.type==='TEXT'){
      try{ await figma.loadFontAsync({family:'Roboto',style:'Regular'}); rep.characters = 'INFO '+info.length+' CREATED '+created+' FAILS '+fails.length; }catch(e){}
    }
    // store summary in frame name
    if(imgFrame){ imgFrame.name = 'IMAGE_ASSETS N='+created+' TOTAL='+info.length+' FAIL='+fails.length; }
  }catch(e){ console.log('ERR '+e.message); }
  figma.closePlugin();
}
