function fn_createComponent(o){
  try{
    const c=figma.createComponent();
    c.name=o.name; c.x=o.x; c.y=o.y; c.resize(o.w,o.h);
    c.fills=[{type:'SOLID',color:o.fill}];
    if(o.r) c.cornerRadius=o.r;
    if(o.stroke) c.strokes=[{type:'SOLID',color:o.stroke}];
    if(o.stroke) c.strokeWeight=1.5;
    const t=figma.createText();
    t.fontName={family:'Roboto',style:o.tstyle};
    t.fontSize=o.tsize;
    t.characters=o.text;
    t.fills=[{type:'SOLID',color:o.tcolor}];
    c.appendChild(t);
    o.parent.appendChild(c);
    return c;
  }catch(e){ console.log('comp err '+o.name+':'+e.message); return null; }
}
